-- Migration 202609270012
-- Validate entries by original transaction currency.
CREATE OR REPLACE FUNCTION public.validate_financial_entry_balance(p_entry_id text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $ DECLARE v_debit_sum numeric; v_credit_sum numeric; v_diff numeric; v_currency_count integer; BEGIN SELECT COUNT(DISTINCT currency_original_no) INTO v_currency_count FROM public.account_trans WHERE main_entry_id = p_entry_id; IF v_currency_count > 1 THEN RAISE EXCEPTION 'القيد يحتوي على أكثر من عملة أصلية: %.', v_currency_count; END IF; SELECT COALESCE(SUM(amount_original) FILTER (WHERE trans_type = 'Debit'),0), COALESCE(SUM(amount_original) FILTER (WHERE trans_type = 'Credit'),0) INTO v_debit_sum,v_credit_sum FROM public.account_trans WHERE main_entry_id=p_entry_id; v_diff:=ABS(v_debit_sum-v_credit_sum); IF v_diff>0.05 THEN RAISE EXCEPTION 'القيد غير متوازن بالعملة الأصلية: الفرق %',v_diff; END IF; END; $;
